-- 002: descuento global y usos por cliente. No recalcula importes históricos.
CREATE TABLE IF NOT EXISTS "PromotionRules" (
 "PromotionId" INTEGER PRIMARY KEY, "MaxPurchasesPerCustomer" INTEGER NOT NULL DEFAULT 1,
 FOREIGN KEY("PromotionId") REFERENCES "Promotions"("Id") ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "PromotionUses" (
 "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "PromotionId" INTEGER NOT NULL, "CustomerId" INTEGER NOT NULL,
 "SaleId" INTEGER NULL, "OrderId" INTEGER NULL,
 FOREIGN KEY("PromotionId") REFERENCES "Promotions"("Id") ON DELETE RESTRICT,
 FOREIGN KEY("CustomerId") REFERENCES "Customers"("Id") ON DELETE RESTRICT,
 FOREIGN KEY("SaleId") REFERENCES "Sales"("Id") ON DELETE RESTRICT,
 FOREIGN KEY("OrderId") REFERENCES "Orders"("Id") ON DELETE RESTRICT
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_PromotionUses_PromotionId_SaleId" ON "PromotionUses"("PromotionId","SaleId");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_PromotionUses_PromotionId_OrderId" ON "PromotionUses"("PromotionId","OrderId");
CREATE INDEX IF NOT EXISTS "IX_PromotionUses_CustomerId_PromotionId" ON "PromotionUses"("CustomerId","PromotionId");
CREATE INDEX IF NOT EXISTS "IX_PromotionUses_SaleId" ON "PromotionUses"("SaleId");
CREATE INDEX IF NOT EXISTS "IX_PromotionUses_OrderId" ON "PromotionUses"("OrderId");
INSERT INTO "PromotionRules"("PromotionId","MaxPurchasesPerCustomer")
 SELECT p."Id",1 FROM "Promotions" p WHERE NOT EXISTS(SELECT 1 FROM "PromotionRules" r WHERE r."PromotionId"=p."Id");
-- Recupera usos anteriores identificables por el nombre histórico de la promoción.
INSERT INTO "PromotionUses"("PromotionId","CustomerId","SaleId")
 SELECT DISTINCT p."Id",s."CustomerId",s."Id" FROM "Sales" s JOIN "SaleLine" l ON l."SaleId"=s."Id"
 JOIN "Promotions" p ON p."Name"=l."Promotion"
 WHERE s."CustomerId" IS NOT NULL AND l."Discount">0
 AND NOT EXISTS(SELECT 1 FROM "Orders" o WHERE o."SaleId"=s."Id")
 AND NOT EXISTS(SELECT 1 FROM "PromotionUses" u WHERE u."PromotionId"=p."Id" AND u."SaleId"=s."Id");
INSERT INTO "PromotionUses"("PromotionId","CustomerId","OrderId")
 SELECT DISTINCT p."Id",o."CustomerId",o."Id" FROM "Orders" o JOIN "OrderLines" l ON l."OrderId"=o."Id"
 JOIN "Promotions" p ON p."Name"=l."Promotion"
 WHERE o."CustomerId" IS NOT NULL AND l."Discount">0 AND o."Status"<>'CANCELADO'
 AND NOT EXISTS(SELECT 1 FROM "PromotionUses" u WHERE u."PromotionId"=p."Id" AND u."OrderId"=o."Id");
INSERT INTO "GozoSchemaVersions"("Version","AppliedUtc") VALUES('002-sale-promotions',CURRENT_TIMESTAMP) ON CONFLICT("Version") DO NOTHING;
